function patternInvertedMirroredRightTriangle(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < i; j++) row += ' ';
    for (let k = 0; k < n - i; k++) row += '*';
    rows.push(row);
  }
  return rows.join('\n');
}

